1	import type { ReactNode } from "react";
2	
3	// Presentational helpers for the published-sites registry. Not a route — only
4	// page/layout/route filenames are routable — so this file is safe to sit inside
5	// app/admin/sites/.
6	//
7	// Deliberately a LOCAL copy of the vocabulary in app/admin/users/ui.tsx rather
8	// than an import from it: that subtree belongs to another surface, and a shared
9	// presentational module that either side can retune turns a styling change over
10	// there into a visual regression over here. The vocabulary is copied on purpose
11	// (rounded-xl hairline borders, text-sm, tabular-nums on every figure,
12	// monochrome except where a colour carries meaning) so the panels still read as
13	// one product.
14	
15	export function formatDateTime(d: Date): string {
16	  return d.toISOString().replace("T", " ").slice(0, 19);
17	}
18	
19	export function formatDate(d: Date): string {
20	  return d.toISOString().slice(0, 10);
21	}
22	
23	export function truncate(text: string, max = 60): string {
24	  return text.length > max ? `${text.slice(0, max)}…` : text;
25	}
26	
27	/**
28	 * Every string rendered from a finding passes through here.
29	 *
30	 * `evidence` is a snippet of SOMEONE ELSE'S site — the whole point of this
31	 * panel is to review it without turning the admin into a content reader. The
32	 * scanner already caps a snippet at roughly 180 characters (EVIDENCE_RADIUS on
33	 * both sides of the match, lib/moderation.ts) but that is the scanner's
34	 * promise, not this page's, and the column is free text in the database. This
35	 * re-truncates hard and never offers the untruncated string anywhere — no
36	 * `title` tooltip, no expander. If a reviewer needs more than this, the answer
37	 * is to open the published site itself, not to read the file out of the panel.
38	 */
39	export const EVIDENCE_MAX = 150;
40	
41	export function evidenceText(evidence: string): string {
42	  return truncate(evidence.replace(/\s+/g, " ").trim(), EVIDENCE_MAX);
43	}
44	
45	// Same derivation as app/api/projects/[id]/publish/route.ts, so the hostname
46	// shown here is the one that route hands the customer.
47	const SITES_BASE = process.env.KODELY_SITES_BASE ?? "kodely.site";
48	
49	/** The public hostname a published project answers on. */
50	export function siteHost(slug: string): string {
51	  return `${slug}.${SITES_BASE}`;
52	}
53	
54	// ── Severity ───────────────────────────────────────────────────────────────
55	// Stored as free text ("high" | "medium" | "low"), so everything here has to
56	// survive a value that is none of those.
57	
58	export type Severity = "high" | "medium" | "low";
59	
60	const SEVERITY_ORDER: Record<string, number> = { high: 0, medium: 1, low: 2 };
61	
62	/** Sort key. Unknown severities sort last rather than disappearing. */
63	export function severityRank(severity: string): number {
64	  return SEVERITY_ORDER[severity] ?? 99;
65	}
66	
67	export function severityClass(severity: string): string {
68	  if (severity === "high") return "text-red-600 dark:text-red-400";
69	  if (severity === "medium") return "text-amber-600 dark:text-amber-500";
70	  if (severity === "low") return "text-black/50 dark:text-white/50";
71	  return "text-black/40 dark:text-white/40";
72	}
73	
74	export function SeverityBadge({ severity }: { severity: string }) {
75	  return (
76	    <span className={`text-xs font-medium uppercase tracking-wide ${severityClass(severity)}`}>
77	      {severity}
78	    </span>
79	  );
80	}
81	
82	export function outcomeLabel(outcome: string | null): string {
83	  if (outcome === "true_positive") return "True positive";
84	  if (outcome === "false_positive") return "False positive";
85	  if (outcome === null) return "Unreviewed";
86	  return outcome;
87	}
88	
89	export function outcomeClass(outcome: string | null): string {
90	  if (outcome === "true_positive") return "text-red-600 dark:text-red-400";
91	  if (outcome === "false_positive") return "text-emerald-600 dark:text-emerald-400";
92	  return "text-black/50 dark:text-white/50";
93	}
94	
95	// ── What the rules actually mean ───────────────────────────────────────────
96	// ModerationFinding stores `rule` but NOT the `note` that lib/moderation.ts
97	// attaches to a live finding — so by the time a row is in the database, the one
98	// sentence that tells a reviewer what tripped is gone. This is that sentence,
99	// transcribed from the rule definitions in lib/moderation.ts.
100	//
101	// Keep in step with lib/moderation.ts. A rule that isn't listed here still
102	// renders (its id is shown raw) — it just loses the explanation, which is the
103	// right failure mode when a new rule ships before this map is updated.
104	
105	export const RULE_NOTES: Record<string, string> = {
106	  "brand-impersonation-credential-form":
107	    "A password field on a page that asks the visitor to sign in to, or verify, someone else's branded account. Three signals had to line up: a real password input, a named brand, and second-person credential solicitation within ~120 characters of it.",
108	  "brand-mention-near-credential-form":
109	    "A third-party brand is named in a file that also has a password field, but with no credential solicitation nearby. Usually an integration list, a partner logo or an OAuth button — recorded for context, never blocking.",
110	  "credential-exfil-channel":
111	    "A password field submits to a known credential drop channel (Telegram bot, Discord webhook, off-origin .php collector, or a form relay wired directly to the password form). Those are drop sites, not form backends.",
112	  "credential-post-off-origin":
113	    "A file with a password field POSTs to an off-origin URL. Legitimate when that URL is the site owner's own backend, which the scanner cannot tell from a drop site — so it records rather than blocks.",
114	  "wallet-seed-phrase-capture":
115	    "An input field asks for a wallet seed / recovery phrase or private key. No legitimate site collects these. Downgraded to low when the surrounding copy reads as a warning not to share one.",
116	  "wallet-drainer-approval":
117	    "The page connects a browser wallet and then asks for an asset-delegation primitive (setApprovalForAll, unlimited allowance, off-chain Permit signature) — permission to move assets it does not own. That is a drainer, not a payment.",
118	  "wallet-connect-present":
119	    "The page connects a browser wallet. Unusual for a generated static site — the build foundation ships no web3 dependencies — but not abusive on its own.",
120	  "password-form-on-static-site":
121	    "A password input on a statically hosted site with no backend, so it cannot authenticate anyone. Mock login UIs and design demos are a real, legitimate thing people build. Context only.",
122	  "runtime-obfuscated-payload":
123	    "Code decodes a string and executes it at runtime (eval of atob, new Function of unescape, and friends). Minifiers never emit this shape; it is normally used to hide a destination URL.",
124	};
125	
126	/**
127	 * Why a site was taken down, from a closed list. Free text is avoided on
128	 * purpose: AdminAuditLog.meta is documented as "small, non-PII context", and a
129	 * free-text box on a takedown form is exactly where someone would paste a
130	 * reporter's email address or a snippet of the offending page. The report
131	 * thread stays the place for the narrative.
132	 */
133	export const TAKEDOWN_REASONS: Record<string, string> = {
134	  abuse_report: "Inbound abuse report",
135	  moderation_finding: "Confirmed moderation finding",
136	  phishing: "Phishing / brand impersonation",
137	  malware: "Malware or wallet drainer",
138	  spam: "Spam / SEO farm",
139	  legal: "Legal or registrar request",
140	  other: "Other (see the report thread)",
141	};
142	
143	// ── Layout primitives ──────────────────────────────────────────────────────
144	
145	export function StatTile({
146	  label,
147	  value,
148	  hint,
149	  tone,
150	}: {
151	  label: string;
152	  value: ReactNode;
153	  hint?: ReactNode;
154	  tone?: "warn" | "bad";
155	}) {
156	  const toneClass =
157	    tone === "bad"
158	      ? "text-red-600 dark:text-red-400"
159	      : tone === "warn"
160	        ? "text-amber-600 dark:text-amber-500"
161	        : "";
162	  return (
163	    <div className="rounded-xl border border-black/10 p-4 dark:border-white/10">
164	      <div className="text-xs text-black/50 dark:text-white/50">{label}</div>
165	      <div className={`mt-1 text-xl font-semibold tabular-nums ${toneClass}`}>{value}</div>
