3	import { revalidatePath } from "next/cache";
4	import { notFound, redirect } from "next/navigation";
5	import { db } from "@/lib/db";
6	import { getAdminUser } from "@/lib/auth";
7	import { TAKEDOWN_REASONS } from "./ui";
8	
9	// The only two mutations this surface has: recording a moderation review, and
10	// taking a published site offline. There is deliberately no delete, no edit and
11	// no "publish on someone's behalf" — the panel reviews other people's private
12	// work, and the strongest guarantee it can offer is that it cannot alter it.
13	//
14	// Server Functions are reachable by direct POST, not only through this UI, so
15	// every one of them re-checks getAdminUser() itself. app/admin/layout.tsx does
16	// not sit in front of an action invocation, and neither does the page's own
17	// check — an attacker POSTing an action id never renders the page at all.
18	// 404 rather than 403, for the same reason the pages use notFound(): a
19	// non-admin learns nothing about what exists here.
20	
21	const REVIEW_OUTCOMES = new Set(["true_positive", "false_positive"]);
22	
23	export async function reviewFinding(formData: FormData): Promise<void> {
24	  const admin = await getAdminUser();
25	  if (!admin) notFound();
26	
27	  const findingId = String(formData.get("findingId") ?? "");
28	  const outcome = String(formData.get("outcome") ?? "");
29	  if (!findingId || !REVIEW_OUTCOMES.has(outcome)) notFound();
30	
31	  const finding = await db.moderationFinding.findUnique({
32	    where: { id: findingId },
33	    select: { id: true, projectId: true },
34	  });
35	  if (!finding) notFound();
36	
37	  // Re-reviewing an already-reviewed finding overwrites the verdict rather than
38	  // appending — the column set only holds one, and an operator correcting their
39	  // own mistake matters more than the history of the correction. The takedown
40	  // it may have justified is separately in AdminAuditLog either way.
41	  await db.moderationFinding.update({
42	    where: { id: findingId },
43	    data: {
44	      reviewedAt: new Date(),
45	      // Email, matching AdminAuditLog.actorEmail and SupportNote.authorEmail —
46	      // an id here would need a join to mean anything to a human.
47	      reviewedBy: admin.email,
48	      outcome,
49	    },
50	  });
51	
52	  revalidatePath(`/admin/sites/${finding.projectId}`);
53	  revalidatePath("/admin/sites");
54	}
55	
56	/**
57	 * Takes a published site offline by clearing `publishedAt`.
58	 *
59	 * That single column is what makes a site live: app/api/site/[slug]/[[...path]]
60	 * answers 404 for every path — pages, assets, and the synthesised robots.txt
61	 * and sitemap.xml alike — the moment it is null, and proxy.ts rewrites
62	 * <slug>.kodely.site into that route with no state of its own. Nothing else is
63	 * consulted.
64	 *
65	 * Nothing is deleted. The published file rows stay exactly where they are, the
66	 * draft tree is untouched, and the project keeps its slug — so the owner still
67	 * has all of their work and can republish it themselves from the project page.
68	 */
69	export async function takeDownSite(formData: FormData): Promise<void> {
70	  const admin = await getAdminUser();
71	  if (!admin) notFound();
72	
73	  const projectId = String(formData.get("projectId") ?? "");
74	  const confirmSlug = String(formData.get("confirmSlug") ?? "").trim();
75	  const reason = String(formData.get("reason") ?? "");
76	  if (!projectId) notFound();
77	
78	  const project = await db.project.findUnique({
79	    where: { id: projectId },
80	    select: { id: true, slug: true, userId: true, publishedAt: true },
81	  });
82	  if (!project) notFound();
83	
84	  // Already offline — someone took it down in another tab, or the owner never
85	  // republished. Not an error, just nothing left to do.
86	  if (!project.publishedAt) {
87	    redirect(`/admin/sites/${projectId}?takedown=already`);
88	  }
89	
90	  if (!TAKEDOWN_REASONS[reason]) {
91	    redirect(`/admin/sites/${projectId}/takedown?error=reason`);
92	  }
93	
94	  // The confirmation step. Typing the slug is the whole guard against taking
95	  // down the wrong site from a list of near-identical rows, so it is checked
96	  // HERE and not only in the browser.
97	  if (confirmSlug !== project.slug) {
98	    redirect(`/admin/sites/${projectId}/takedown?error=slug`);
99	  }
100	
101	  await db.$transaction([
102	    db.project.update({ where: { id: projectId }, data: { publishedAt: null } }),
103	    // Append-only, and written in the same transaction as the takedown so a
104	    // site can never go dark with no record of who darkened it. "site.taken_down"
105	    // is the action name the AdminAuditLog model itself gives as an example.
106	    db.adminAuditLog.create({
107	      data: {
108	        actorId: admin.id,
109	        actorEmail: admin.email,
110	        action: "site.taken_down",
111	        targetType: "project",
112	        targetId: projectId,
113	        meta: {
114	          slug: project.slug,
115	          ownerId: project.userId,
116	          reason,
117	          // What the site's live-since timestamp was, since the column that
118	          // held it is about to be null.
119	          publishedAt: project.publishedAt.toISOString(),
120	        },
121	      },
122	    }),
123	  ]);
124	
125	  revalidatePath(`/admin/sites/${projectId}`);
126	  revalidatePath("/admin/sites");
127	  redirect(`/admin/sites/${projectId}?takedown=done`);
128	}
