// Resolves the project's extensionless relative imports ("./db") to "./db.ts"
// so Node can execute the real TypeScript sources with its built-in type
// stripping. Nothing else is altered — the modules that run are the real ones.
export async function resolve(specifier, context, next) {
  if (specifier.startsWith("./") || specifier.startsWith("../")) {
    try {
      return await next(specifier, context);
    } catch {
      return await next(`${specifier}.ts`, context);
    }
  }
  return next(specifier, context);
}

